function tallyRanges(values, queries) {
  return queries.map(([left, right]) => {
    let total = 0;
    for (let i = left; i <= right; i++) total += values[i];
    return total;
  });
}

function tallyRanges(values, queries) {
  const prefix = [0];
  for (const v of values) prefix.push(prefix[prefix.length - 1] + v);
  return queries.map(([left, right]) => prefix[right + 1] - prefix[left]);
}
